using BARANG.Core.Domain.Files;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Domain.Security;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class FileConfigurationBase
{
    public static void Company<T>(EntityTypeBuilder<T>b,string table) where T:class { b.ToTable(table);b.HasKey("Id").HasName($"pk_{table}");b.Property<Guid>("Id").HasColumnName("id").ValueGeneratedNever();b.Property<Guid>("CompanyId").HasColumnName("company_id");b.HasOne<Company>().WithMany().HasForeignKey("CompanyId").OnDelete(DeleteBehavior.Restrict);b.HasAlternateKey("CompanyId","Id").HasName($"ak_{table}_company_id_id"); }
}
internal sealed class ArtworkConfiguration:IEntityTypeConfiguration<Artwork>{public void Configure(EntityTypeBuilder<Artwork>b){FileConfigurationBase.Company(b,"artworks");b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50);b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(200);b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(2000);b.Property(x=>x.CategoryCode).HasColumnName("category_code").HasMaxLength(50);b.Property(x=>x.DesignerUserId).HasColumnName("designer_user_id");b.Property(x=>x.LifecycleStatus).HasColumnName("lifecycle_status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.CurrentVersionId).HasColumnName("current_version_id");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.IsArchived).HasColumnName("is_archived");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.DesignerUserId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.Code}).IsUnique().HasDatabaseName("uq_artworks_company_code");b.HasIndex(x=>new{x.CompanyId,x.IsActive,x.IsArchived,x.Code}).HasDatabaseName("ix_artworks_options");}}
internal sealed class ArtworkVersionConfiguration:IEntityTypeConfiguration<ArtworkVersion>{public void Configure(EntityTypeBuilder<ArtworkVersion>b){FileConfigurationBase.Company(b,"artwork_versions");b.Property(x=>x.ArtworkId).HasColumnName("artwork_id");b.Property(x=>x.VersionNumber).HasColumnName("version_number");b.Property(x=>x.FileVersionId).HasColumnName("file_version_id");b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.HasOne<Artwork>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ArtworkId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<FileVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.ArtworkId,x.VersionNumber}).IsUnique().HasDatabaseName("uq_artwork_versions_number");}}
internal sealed class ArtworkTagConfiguration:IEntityTypeConfiguration<ArtworkTag>{public void Configure(EntityTypeBuilder<ArtworkTag>b){FileConfigurationBase.Company(b,"artwork_tags");b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50);b.Property(x=>x.DisplayName).HasColumnName("display_name").HasMaxLength(100);b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Code}).IsUnique().HasDatabaseName("uq_artwork_tags_company_code");}}
internal sealed class ArtworkTagAssignmentConfiguration:IEntityTypeConfiguration<ArtworkTagAssignment>{public void Configure(EntityTypeBuilder<ArtworkTagAssignment>b){FileConfigurationBase.Company(b,"artwork_tag_assignments");b.Property(x=>x.ArtworkId).HasColumnName("artwork_id");b.Property(x=>x.TagId).HasColumnName("tag_id");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.IsActive).HasColumnName("is_active");b.HasOne<Artwork>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ArtworkId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ArtworkTag>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.TagId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.ArtworkId,x.TagId}).IsUnique().HasDatabaseName("uq_artwork_tag_assignments");}}
internal sealed class StoredFileConfiguration:IEntityTypeConfiguration<StoredFile>{public void Configure(EntityTypeBuilder<StoredFile>b){FileConfigurationBase.Company(b,"stored_files");b.Property(x=>x.UploadedByUserId).HasColumnName("uploaded_by_user_id");b.Property(x=>x.CurrentVersionId).HasColumnName("current_version_id");b.Property(x=>x.IsArchived).HasColumnName("is_archived");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.UploadedByUserId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class FileVersionConfiguration:IEntityTypeConfiguration<FileVersion>{public void Configure(EntityTypeBuilder<FileVersion>b){FileConfigurationBase.Company(b,"file_versions");b.Property(x=>x.FileId).HasColumnName("file_id");b.Property(x=>x.VersionNumber).HasColumnName("version_number");b.Property(x=>x.StorageProvider).HasColumnName("storage_provider").HasMaxLength(30);b.Property(x=>x.StorageBucket).HasColumnName("storage_bucket").HasMaxLength(100);b.Property(x=>x.StorageKey).HasColumnName("storage_key").HasMaxLength(500);b.Property(x=>x.OriginalFileName).HasColumnName("original_file_name").HasMaxLength(255);b.Property(x=>x.MediaType).HasColumnName("media_type").HasMaxLength(100);b.Property(x=>x.Extension).HasColumnName("extension").HasMaxLength(20);b.Property(x=>x.SizeBytes).HasColumnName("size_bytes");b.Property(x=>x.Sha256Hash).HasColumnName("sha256_hash").HasMaxLength(64);b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.ProcessingStatus).HasColumnName("processing_status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.IsArchived).HasColumnName("is_archived");b.HasOne<StoredFile>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.FileId,x.VersionNumber}).IsUnique().HasDatabaseName("uq_file_versions_number");b.HasIndex(x=>new{x.CompanyId,x.Sha256Hash}).HasDatabaseName("ix_file_versions_company_hash");b.HasIndex(x=>x.StorageKey).IsUnique().HasDatabaseName("uq_file_versions_storage_key");}}
internal sealed class FileLinkConfiguration:IEntityTypeConfiguration<FileLink>{public void Configure(EntityTypeBuilder<FileLink>b){FileConfigurationBase.Company(b,"file_links");b.Property(x=>x.FileId).HasColumnName("file_id");b.Property(x=>x.FileVersionId).HasColumnName("file_version_id");b.Property(x=>x.EntityType).HasColumnName("entity_type").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.EntityId).HasColumnName("entity_id");b.Property(x=>x.Purpose).HasColumnName("purpose").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.IsActive).HasColumnName("is_active");b.HasOne<StoredFile>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<FileVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.EntityType,x.EntityId,x.FileId,x.Purpose}).IsUnique().HasDatabaseName("uq_file_links_target");b.HasIndex(x=>new{x.CompanyId,x.EntityType,x.EntityId}).HasDatabaseName("ix_file_links_entity");}}
internal sealed class FileProcessingJobConfiguration:IEntityTypeConfiguration<FileProcessingJob>{public void Configure(EntityTypeBuilder<FileProcessingJob>b){FileConfigurationBase.Company(b,"file_processing_jobs");b.Property(x=>x.FileVersionId).HasColumnName("file_version_id");b.Property(x=>x.JobType).HasColumnName("job_type").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.AttemptCount).HasColumnName("attempt_count");b.Property(x=>x.RequestedAtUtc).HasColumnName("requested_at_utc");b.Property(x=>x.StartedAtUtc).HasColumnName("started_at_utc");b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.Property(x=>x.LastErrorCode).HasColumnName("last_error_code").HasMaxLength(100);b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasOne<FileVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.Status,x.RequestedAtUtc}).HasDatabaseName("ix_file_processing_jobs_pending");}}
internal sealed class FileDerivativeConfiguration:IEntityTypeConfiguration<FileDerivative>{public void Configure(EntityTypeBuilder<FileDerivative>b){FileConfigurationBase.Company(b,"file_derivatives");b.Property(x=>x.SourceFileVersionId).HasColumnName("source_file_version_id");b.Property(x=>x.DerivativeType).HasColumnName("derivative_type").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.StorageKey).HasColumnName("storage_key").HasMaxLength(500);b.Property(x=>x.MediaType).HasColumnName("media_type").HasMaxLength(100);b.Property(x=>x.SizeBytes).HasColumnName("size_bytes");b.Property(x=>x.Sha256Hash).HasColumnName("sha256_hash").HasMaxLength(64);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.HasOne<FileVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SourceFileVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.SourceFileVersionId,x.DerivativeType}).IsUnique().HasDatabaseName("uq_file_derivatives_type");}}
